 path=p['path'];ids=[r['id'] for r in rows if path in r['paths']];cfs=content[path]['findings'];cids=list(dict.fromkeys(re.match(r'CONT-\d+',f['defect'])[0] for f in cfs));x=pf.get(path)
 perftext=f"{x['scores']['performance']}/{x['scores']['accessibility']}/{x['scores']['best-practices']}/{x['scores']['seo']} ; {x['lcp_ms']/1000:.3f} s ; {x['cls']:.4f}" if x else 'Noindex : non mesuré en labo'
